// Texture names across Minecraft versions (docs/DECISIONS.md #19, #89).
// The table is generated by scripts/generate-texture-renames.mjs.

import { MINECRAFT_VERSIONS } from './minecraft-versions'
import { RENAME_TABLE } from './texture-renames.data'
import { PACK_TEXTURE_PREFIX } from './textures'

interface RenameStep {
  /** Position of the version that introduced the new names in MINECRAFT_VERSIONS. */
  index: number
  forward: ReadonlyMap<string, string>
  backward: ReadonlyMap<string, string>
}

const versionIndex = new Map(MINECRAFT_VERSIONS.map((version, index) => [version.id, index]))

function indexOf(versionId: string): number {
  const index = versionIndex.get(versionId)
  if (index === undefined) throw new Error(`Unknown Minecraft version ${versionId}`)
  return index
}

export const RENAME_STEPS: readonly RenameStep[] = RENAME_TABLE.map((step) => {
  const forward = new Map(Object.entries(step.renames))
  const backward = new Map([...forward].map(([from, to]) => [to, from]))
  return { index: indexOf(step.version), forward, backward }
}).sort((a, b) => a.index - b.index)

/**
 * Number of rename steps up to and including a version. Versions with the same era use the
 * same texture names, so one ZIP can serve all of them.
 */
export function renameEra(versionId: string): number {
  const index = indexOf(versionId)
  return RENAME_STEPS.filter((step) => step.index <= index).length
}

/** Where a texture (path below assets/minecraft/textures/) of one version lives in another. */
export function translateTexturePath(path: string, from: string, to: string): string {
  const start = indexOf(from)
  const end = indexOf(to)
  let result = path
  if (end > start) {
    for (const step of RENAME_STEPS) {
      if (step.index > start && step.index <= end) result = step.forward.get(result) ?? result
    }
  } else if (end < start) {
    for (const step of [...RENAME_STEPS].reverse()) {
      if (step.index > end && step.index <= start) result = step.backward.get(result) ?? result
    }
  }
  return result
}

/** Translates a pack file path; textures and their .png.mcmeta move together, other files stay. */
export function translatePackPath(path: string, from: string, to: string): string {
  if (!path.startsWith(PACK_TEXTURE_PREFIX)) return path
  const relative = path.slice(PACK_TEXTURE_PREFIX.length)
  const suffix = relative.endsWith('.png.mcmeta') ? '.mcmeta' : ''
  const texture = relative.slice(0, relative.length - suffix.length)
  if (!texture.endsWith('.png')) return path
  return `${PACK_TEXTURE_PREFIX}${translateTexturePath(texture, from, to)}${suffix}`
}
